begin;
create temp table _truoc as select count(*) n from public.question_bank;
insert into public.question_bank (subject_code, grade, topic_id, topic_name, form, qtype, difficulty, difficulty_source, question, content_hash, archived, note)
select 'vat-ly', '10', v.tid, v.tname, 'bai_tap', v.q->>'type', v.q->>'difficulty', 'ai', v.q, public.question_content_hash(v.q), true, 'nap-vl10-c5-20261020'
from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Độ biến thiên động lượng của một vật","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Biểu thức của định luật II Newton còn được viết dưới dạng nào sau đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật II Newton: gia tốc của một vật cùng hướng với lực tác dụng lên vật, có độ lớn tỉ lệ thuận với độ lớn của lực và tỉ lệ nghịch với khối lượng của vật.</p><p class=\"text-base leading-relaxed my-2\">Biểu thức: $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{F}=m\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{a}$, trong đó $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{a}$ là gia tốc.</p><p class=\"text-base leading-relaxed my-2\">Gia tốc là đạo hàm của vận tốc theo thời gian, với độ biến thiên vận tốc trong khoảng thời gian ngắn: $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{a}=\\dfrac{\\Delta\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{F}=m\\dfrac{\\Delta\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">Đáp án D đúng. Phương án C thiếu khối lượng $m$; phương án B dùng độ lớn $\\Delta v$ thay cho độ biến thiên vectơ vận tốc.</p>","options":["$\\overset{\\rightarrow}{F}=m\\overset{\\rightarrow}{\\frac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}}.$","$\\overset{\\rightarrow}{F}=m\\frac{\\Delta v}{\\Delta t}.$","$\\overset{\\rightarrow}{F}=\\overset{\\rightarrow}{\\frac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}}.$","$\\overset{\\rightarrow}{F}=m\\frac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}.$"],"answer":3}$q$::jsonb, 143, $q$Độ biến thiên động lượng của một vật$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Độ biến thiên động lượng của một vật","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho chất điểm m chuyển động không vận tốc đầu chỉ dưới tác dụng của lực $\\overset{\\rightarrow}{F}$ không đổi. Động lượng chất điểm ở thời điểm t là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định lí biến thiên động lượng (dạng xung lượng): khi lực $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{F}$ không đổi tác dụng lên chất điểm trong khoảng thời gian $\\Delta t$, độ biến thiên động lượng bằng xung lượng của lực: $\\Delta \\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p} = \\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{F}\\Delta t$.</p><p class=\"text-base leading-relaxed my-2\">Chất điểm bắt đầu chuyển động từ trạng thái nghỉ nên động lượng ban đầu $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p}_0 = \\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{0}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p} - \\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p}_0 = \\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{F}\\Delta t$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p} = \\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{F}\\Delta t$ (với $\\Delta t = t$ là thời gian tính từ lúc bắt đầu chuyển động).</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án còn lại: A và D có thứ nguyên sai (chứa khối lượng $m$ trong khi động lượng không phụ thuộc trực tiếp như vậy); C bị lỗi công thức và không đúng dạng $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{F}\\Delta t$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <b>B</b>, $p = F\\Delta t$.</p>","options":["$p = \\overset{\\rightarrow}{F}m\\Delta t.$","$p = \\overset{\\rightarrow}{F}\\Delta t.$","$p = \\frac{F}{\\Delta}tm.$","$p = \\overset{\\rightarrow}{F}m.$"],"answer":1}$q$::jsonb, 143, $q$Độ biến thiên động lượng của một vật$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Khái niệm động lượng, xung lượng của lực","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Biểu thức $p = \\sqrt{p_{1}^{2}} + p_{2}^{2}$ là biểu thức tính độ lớn tổng động lượng của hệ trong trường hợp hai véctơ vận tốc</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của hệ hai vật là tổng vectơ: $\\vec{p} = \\vec{p}_1 + \\vec{p}_2$.</p><p class=\"text-base leading-relaxed my-2\">Độ lớn của tổng hai vectơ được tính theo định lí hàm cos: $p^2 = p_1^2 + p_2^2 + 2p_1p_2\\cos\\alpha$, với $\\alpha$ là góc giữa $\\vec{p}_1$ và $\\vec{p}_2$.</p><p class=\"text-base leading-relaxed my-2\">Biểu thức đề cho $p = \\sqrt{p_1^2 + p_2^2}$ tương ứng với $\\cos\\alpha = 0$, tức $\\alpha = 90^{0}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Hai vectơ vận tốc (cùng với hai vectơ động lượng) vuông góc với nhau.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các đáp án khác: cùng hướng cho $p = p_1 + p_2$; ngược chiều cho $p = |p_1 - p_2|$; hợp góc $60^{0}$ cho $p^2 = p_1^2 + p_2^2 + p_1p_2$ (không khớp).</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng: C.</p>","options":["cùng hướng.","cùng phương ngược chiều.","vuông góc với nhau.","hợp với nhau một góc 60$^{0}$."],"answer":2}$q$::jsonb, 142, $q$Khái niệm động lượng, xung lượng của lực$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Khái niệm động lượng, xung lượng của lực","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một ô tô A có khối lượng m đang chuyển động với vận tốc $v_{1}$ đuổi theo một ô tô B có khối lượng $m_{2}$ chuyển động với vận tốc $ v_{2}$. Động lượng của xe A đối với hệ quy chiếu gắn với xe B là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của vật trong một hệ quy chiếu được xác định theo vận tốc của vật đối với hệ quy chiếu đó: $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p}=m\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}$, trong đó $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}$ là vận tốc của vật đối với hệ quy chiếu đang xét.</p><p class=\"text-base leading-relaxed my-2\">Vận tốc của xe A đối với xe B (theo quy tắc cộng vận tốc cổ điển): $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{AB}=\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{1}-\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{2}$, với $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{1}$ là vận tốc của A và $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{2}$ là vận tốc của B đối với đường (hệ quy chiếu đứng yên).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Động lượng của xe A đối với hệ quy chiếu gắn với xe B: $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p}_{AB}=m\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{AB}=m\\left(\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{1}-\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{2}\\right)$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là A.</p>","options":["${\\overset{\\rightarrow}{p}}_{AB}=m\\left( v \\right)_{1}-v_{2}.$","${\\overset{\\rightarrow}{p}}_{AB}= -m\\left( v \\right)_{1}-v_{2}.$","${\\overset{\\rightarrow}{p}}_{AB}=m\\left( v \\right)_{1}+v_{2}.$","${\\overset{\\rightarrow}{p}}_{AB}= -m\\left( v \\right)_{1}+v_{2}.$"],"answer":0}$q$::jsonb, 142, $q$Khái niệm động lượng, xung lượng của lực$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Khái niệm động lượng, xung lượng của lực","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai vật có khối lượng $m_{1},$$m_{2}$ chuyển động với vận tốc ${\\overset{\\rightarrow}{v}}_{1}$ và ${\\overset{\\rightarrow}{v}}_{2}.$ Động lượng của hệ có giá trị</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của một vật là $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p}=m\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}$. Động lượng của hệ hai vật là tổng vectơ động lượng của từng vật (động lượng là đại lượng vectơ nên phải cộng theo quy tắc hình bình hành):</p><p class=\"text-base leading-relaxed my-2\">$\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p}=\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p_1}+\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p_2}=m_1\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_1}+m_2\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_2}$</p><p class=\"text-base leading-relaxed my-2\">Trong các phương án, chỉ có $m_1\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_1}+m_2\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_2}$ đúng. Phương án A chỉ đúng khi hệ có một vận tốc chung, còn phương án C chỉ đúng khi tổng động lượng bằng 0.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: động lượng của hệ là $m_1\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_1}+m_2\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_2}$, chọn <b>B</b>.</p>","options":["$m\\overset{\\rightarrow}{v}.$","$m_{1}v_{1}+m_{2}v_{2}.$","0.","$m_{1}v_{1}+m_{2}v_{2}.$"],"answer":1}$q$::jsonb, 142, $q$Khái niệm động lượng, xung lượng của lực$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Khái niệm động lượng, xung lượng của lực","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai vật có cùng khối lượng m, chuyển động với vận tốc có độ lớn bằng nhau. Hệ thức tính động lượng của hệ hai vật là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của hệ hai vật là tổng véc tơ động lượng của từng vật: $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p}=\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p_1}+\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p_2}$.</p><p class=\"text-base leading-relaxed my-2\">Với mỗi vật, động lượng là $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p_i}=m\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_i}$, nên $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p}=m\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_1}+m\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_2}=m\\left(\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_1}+\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v_2}\\right)$.</p><p class=\"text-base leading-relaxed my-2\">Phương án A và B chỉ đúng khi hai véc tơ vận tốc trùng nhau về cả hướng lẫn độ lớn, đề bài không nói điều này nên loại. Phương án D là đại lượng vô hướng, không đúng vì động lượng là đại lượng véc tơ.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là C.</p>","options":["$\\overset{\\rightarrow}{p}=2m{\\overset{\\rightarrow}{v}}_{1}.$","$\\overset{\\rightarrow}{p}=2m{\\overset{\\rightarrow}{v}}_{2}.$","$\\overset{\\rightarrow}{p}=m\\left( {\\overset{\\rightarrow}{v}}_{1} \\right)+{\\overset{\\rightarrow}{v}}_{2}.$","$p=m\\left( v_{1} \\right)+v_{2}.$"],"answer":2}$q$::jsonb, 142, $q$Khái niệm động lượng, xung lượng của lực$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Khái niệm động lượng, xung lượng của lực","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một ô tô khối lượng 1 tấn khởi hành từ trạng thái nghỉ có gia tốc không đổi là 1 m/s$^{2}$. Biết ô tô đi được quãng đường 50 m.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Ô tô chuyển động thẳng nhanh dần đều từ nghỉ: $m=1000$ kg, $v_0=0$, $a=1$ m/s$^2$, $s=50$ m.</p><p class=\"text-base leading-relaxed my-2\">a) $v^2=2as=2\\cdot1\\cdot50=100$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v=10$ m/s, không phải 20 m/s. Ý a <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">b) $p=mv=1000\\cdot10=10000$ kg.m/s, khác $20000\\sqrt5$ kg.m/s. Ý b <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">c) $v=30$ m/s: $p=mv=1000\\cdot30=30000$ kg.m/s, khác 32000. Ý c <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">d) $p=mv$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v=\\dfrac{p}{m}=\\dfrac{25000}{1000}=25$ m/s. Ý d <b>Đúng</b>.</p>","statements":[{"text":"Vận tốc của ô tô sai khi đi được 50 m là 20 m/s.","answer":false},{"text":"Động lượng của ô tô là $20000\\sqrt{5} kg.m/s$","answer":false},{"text":"Khi ô tô đạt vận tốc 30 m/s thì động lượng của ô tô là 32000 k g . m / s","answer":false},{"text":"Để động lượng của ô tô là 25000 k g . m / s thì vận tốc của ô tô là 25 m/s.","answer":true}]}$q$::jsonb, 142, $q$Khái niệm động lượng, xung lượng của lực$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Khái niệm động lượng, xung lượng của lực","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho một hệ gồm 2 vật chuyển động. Vật 1 có khối lượng 2 kg có vận tốc có độ lớn 4 m/s. Vật 2 có khối lượng 3 kg có vận tốc độ lớn là 2 m/s.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của vật: $\\vec{p} = m\\vec{v}$, có độ lớn $p = mv$.</p><p class=\"text-base leading-relaxed my-2\">Động lượng của vật 1: $p_1 = m_1v_1 = 2 \\cdot 4 = 8\\ \\text{kg.m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Động lượng của vật 2: $p_2 = m_2v_2 = 3 \\cdot 2 = 6\\ \\text{kg.m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Động lượng của hệ: $\\vec{p} = \\vec{p_1} + \\vec{p_2}$, với $p^2 = p_1^2 + p_2^2 + 2p_1p_2\\cos\\alpha$, trong đó $\\alpha$ là góc giữa $\\vec{v_1}$ và $\\vec{v_2}$.</p><p class=\"text-base leading-relaxed my-2\">a) Cùng hướng ($\\alpha = 0^\\circ$): $p = p_1 + p_2 = 8 + 6 = 14\\ \\text{kg.m/s}$. Đúng.</p><p class=\"text-base leading-relaxed my-2\">b) Ngược hướng ($\\alpha = 180^\\circ$): $p = |p_1 - p_2| = |8 - 6| = 2\\ \\text{kg.m/s}$, không phải $6\\ \\text{kg.m/s}$. Sai.</p><p class=\"text-base leading-relaxed my-2\">c) Vuông góc ($\\alpha = 90^\\circ$): $p = \\sqrt{p_1^2 + p_2^2} = \\sqrt{8^2 + 6^2} = \\sqrt{100} = 10\\ \\text{kg.m/s}$, không phải $2\\ \\text{kg.m/s}$. Sai.</p><p class=\"text-base leading-relaxed my-2\">d) Góc $60^\\circ$: $p^2 = 8^2 + 6^2 + 2 \\cdot 8 \\cdot 6 \\cdot \\cos 60^\\circ = 64 + 36 + 48 = 148$, suy ra $p = \\sqrt{148} = 2\\sqrt{37}\\ \\text{kg.m/s}$. Đúng.</p>","statements":[{"text":"Động lượng của hai vật khi v → 2 cùng hướng với v 1 → là 14 k g . m / s","answer":true},{"text":"Động lượng của hai vật khi v → 2 ngược hướng với v 1 → 6 k g . m / s","answer":false},{"text":"Động lượng của hai vật khi v → 2 hướng chếch lên trên, hợp với v 1 → góc 90 0 là 2 k g . m / s","answer":false},{"text":"Động lượng của hai vật khi v → 2 hướng chếch lên trên, hợp với v 1 → góc 60 0 là $2\\sqrt{37} kg.m/s$","answer":true}]}$q$::jsonb, 142, $q$Khái niệm động lượng, xung lượng của lực$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Khái niệm động lượng, xung lượng của lực","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>sai</strong> khi nói về động lượng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của vật là $\\vec{p} = m\\vec{v}$, là đại lượng vectơ có hướng cùng hướng với vận tốc và độ lớn $p = mv$.</p><p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng: với hệ kín (không chịu ngoại lực hoặc tổng ngoại lực bằng 0), tổng động lượng $\\vec{p}_1 + \\vec{p}_2 + \\dots$ của hệ được bảo toàn, tức là không đổi theo thời gian.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Đúng. Trong hệ kín, động lượng của từng vật có thể thay đổi do tương tác với các vật khác trong hệ, miễn là tổng động lượng của hệ không đổi.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng. Động lượng có hướng xác định bởi vận tốc nên là đại lượng vectơ.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng. Độ lớn $p = mv$ là tích khối lượng và vận tốc.</p><p class=\"text-base leading-relaxed my-2\">D. Sai. Động lượng của hệ kín được bảo toàn, nên không thay đổi.</p><p class=\"text-base leading-relaxed my-2\"><b>Đáp án: D</b></p>","options":["Động lượng của mỗi vật trong hệ kín có thể thay đổi.","Động lượng của vật là đại lượng vectơ.","Động lượng của một vật có độ lớn bằng tích khối lượng và vận tốc của vật.","Động lượng của một hệ kín luôn luôn thay đổi."],"answer":3}$q$::jsonb, 142, $q$Khái niệm động lượng, xung lượng của lực$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Khái niệm động lượng, xung lượng của lực","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>sai</strong> khi nói về động lượng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của một vật được xác định bởi công thức véc tơ $\\vec{p} = m\\vec{v}$, trong đó $m$ là khối lượng và $\\vec{v}$ là vận tốc của vật.</p><p class=\"text-base leading-relaxed my-2\">Độ lớn của động lượng: $p = mv$, tức bằng tích khối lượng và tốc độ của vật. Do đó phương án A đúng.</p><p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng: đối với hệ kín (không chịu ngoại lực hoặc tổng ngoại lực bằng không), tổng động lượng của hệ được bảo toàn. Do đó phương án B đúng.</p><p class=\"text-base leading-relaxed my-2\">Động lượng là đại lượng véc tơ, cùng hướng với vận tốc. Do đó phương án D đúng.</p><p class=\"text-base leading-relaxed my-2\">Phương án C nêu độ lớn động lượng bằng $m v^2$, điều này sai vì động lượng tỉ lệ với vận tốc bậc nhất chứ không phải bình phương. Đơn vị $m v^2$ là đơn vị của động năng, không phải động lượng.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: phát biểu sai là phương án C.</p>","options":["Động lượng của một vật có độ lớn bằng tích khối lượng và tốc độ của vật.","Trong hệ kín, động lượng của hệ được bảo toàn.","Động lượng của một vật có độ lớn bằng tích khối lượng và bình phương vận tốc.","Động lượng của một vật là một đại lượng véc tơ."],"answer":2}$q$::jsonb, 142, $q$Khái niệm động lượng, xung lượng của lực$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong> khi nói về động lượng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng: Véc tơ động lượng toàn phần của một hệ kín (không chịu tác dụng của ngoại lực, hoặc tổng ngoại lực bằng 0) được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">$\\vec{p}_{\\text{tr}} = \\vec{p}_{\\text{s}}$ hay $\\sum \\vec{p}_i = \\text{const}$ khi hệ kín.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Sai, thiếu điều kiện \"toàn phần\" và \"hệ kín\". Động lượng của một vật riêng lẻ hoặc của hệ chịu ngoại lực không được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">B. Sai, thiếu điều kiện \"hệ kín\". Nếu hệ có ngoại lực khác không thì động lượng toàn phần không bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng, đây là đúng nội dung định luật bảo toàn động lượng.</p><p class=\"text-base leading-relaxed my-2\">D. Sai, động lượng là đại lượng véc tơ, phát biểu này thiếu tính véc tơ và không nêu rõ \"toàn phần\".</p>","options":["Véc tơ động lượng của hệ được bảo toàn.","Véc tơ động lượng toàn phần của hệ được bảo toàn.","Véc tơ động lượng toàn phần của hệ kín được bảo toàn.","Động lượng của hệ kín được bảo toàn."],"answer":2}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phương trình của định luật bảo toàn động lượng là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng: trong hệ kín (cô lập), tổng động lượng của hệ trước và sau tương tác được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">$\\vec{p}_{1}+\\vec{p}_{2}=\\vec{p}_{1}'+\\vec{p}_{2}'$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m_{1}\\vec{v}_{1}+m_{2}\\vec{v}_{2}=m_{1}\\vec{v}_{1}'+m_{2}\\vec{v}_{2}'$</p><p class=\"text-base leading-relaxed my-2\">Phương án B sai vì viết sai cấu trúc (tổng khối lượng cộng tổng vận tốc). Phương án C sai vì đổi chéo khối lượng và vận tốc. Phương án A và D có cùng nội dung, nhưng trong dạng vectơ đúng của định luật các đại lượng vận tốc phải là vectơ; đề gốc có thể đã mất kí hiệu vectơ khi chuyển từ Word.</p><p class=\"text-base leading-relaxed my-2\">Chọn D.</p>","options":["$m_{1}v_{1} + m_{2}v_{2} = m_{1}v_{1}' + m_{2}v_{2}'.$","$\\left( m_{1} \\right)+m_{2}\\left( v_{1} \\right)+v_{2}=m_{1}v_{1}'+m_{2}v_{2}'.$","$m_{1}v_{2}+m_{2}v_{1}=m_{1}v_{2}'+m_{2}v_{1}'.$","$m_{1}v_{1}+m_{2}v_{2}=m_{1}v_{1}'+m_{2}v_{2}'.$"],"answer":3}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng chỉ <strong>đúng</strong> trong trường hợp</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Định luật bảo toàn động lượng:</strong> Động lượng của một hệ kín (hệ cô lập) được bảo toàn, tức là tổng động lượng $\\vec{p}$ của hệ không đổi theo thời gian.</p><p class=\"text-base leading-relaxed my-2\"><strong>Điều kiện áp dụng:</strong> Hệ cô lập, tức là tổng ngoại lực tác dụng lên hệ bằng 0 (hoặc nội lực lớn hơn rất nhiều so với ngoại lực trong khoảng thời gian tương tác rất ngắn).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\sum \\vec{F}_{ngoại} = 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{\\Delta \\vec{p}}{\\Delta t} = 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\vec{p}_{trước} = \\vec{p}_{sau}$.</p><p class=\"text-base leading-relaxed my-2\"><strong>Xét các phương án:</strong></p><p class=\"text-base leading-relaxed my-2\">A, B: Sai vì ma sát có thể là ngoại lực hoặc nội lực, không quyết định việc bảo toàn động lượng; điều kiện đúng là không có ngoại lực tổng hợp.</p><p class=\"text-base leading-relaxed my-2\">C: Sai vì hệ kín có ma sát vẫn có thể có ngoại lực (ví dụ ma sát với mặt sàn) nên động lượng không chắc bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">D: Đúng vì hệ cô lập thỏa mãn đúng điều kiện tổng ngoại lực bằng 0.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Định luật bảo toàn động lượng chỉ đúng trong trường hợp hệ cô lập. Đáp án <strong>D</strong>.</p>","options":["hệ có ma sát.","hệ không có ma sát.","hệ kín có ma sát.","hệ cô lập."],"answer":3}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng tương đương với định luật</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Xét hệ gồm hai vật tương tác với nhau và không chịu ngoại lực (hệ kín).</p><p class=\"text-base leading-relaxed my-2\">Theo định luật III Newton, lực do vật 1 tác dụng lên vật 2 và lực do vật 2 tác dụng lên vật 1 luôn cùng độ lớn, ngược chiều: $\\vec{F}_{12} = -\\vec{F}_{21}$.</p><p class=\"text-base leading-relaxed my-2\">Theo định luật II Newton dạng động lượng: $\\vec{F}_{12} = \\dfrac{\\Delta \\vec{p}_1}{\\Delta t}$ và $\\vec{F}_{21} = \\dfrac{\\Delta \\vec{p}_2}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{\\Delta \\vec{p}_1}{\\Delta t} = -\\dfrac{\\Delta \\vec{p}_2}{\\Delta t}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\Delta \\vec{p}_1 + \\Delta \\vec{p}_2 = 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\vec{p}_1 + \\vec{p}_2 = \\text{const}$, tức là tổng động lượng của hệ được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">Ngược lại, nếu tổng động lượng của hệ hai vật được bảo toàn thì $\\Delta \\vec{p}_1 = -\\Delta \\vec{p}_2$, suy ra $\\vec{F}_{12} = -\\vec{F}_{21}$, đúng với định luật III Newton.</p><p class=\"text-base leading-relaxed my-2\">Vậy định luật bảo toàn động lượng tương đương với định luật III Newton (đáp án C).</p>","options":["I Newton.","II Newton.","III Newton.","I và III Newton."],"answer":2}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chuyển động bằng phản lực tuân theo</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Đáp án: C. định luật bảo toàn động lượng.</strong></p><p class=\"text-base leading-relaxed my-2\">Chuyển động bằng phản lực xảy ra khi một phần của vật (khí, nhiên liệu cháy) được phụt ra phía sau với vận tốc nhất định, khiến vật chuyển động về phía trước.</p><p class=\"text-base leading-relaxed my-2\">Hệ gồm vật và phần khí phụt ra là hệ kín (bỏ qua ngoại lực so với lực đẩy trong thời gian rất ngắn), nên động lượng của hệ được bảo toàn: $\\vec{p}_{\\text{trước}} = \\vec{p}_{\\text{sau}}$.</p><p class=\"text-base leading-relaxed my-2\">Ban đầu hệ đứng yên nên tổng động lượng bằng 0. Sau khi phụt khí: $m_{\\text{khí}}\\vec{v}_{\\text{khí}} + m_{\\text{vật}}\\vec{v}_{\\text{vật}} = \\vec{0}$, tức phần vật chuyển động ngược hướng với khí phụt ra.</p><p class=\"text-base leading-relaxed my-2\">Vậy chuyển động bằng phản lực tuân theo định luật bảo toàn động lượng.</p>","options":["định luật bảo toàn công.","Định luật II Niu-tơn.","định luật bảo toàn động lượng.","định luật III Niu-tơn."],"answer":2}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một hệ vật gọi là hệ kín nếu</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ kín (hệ cô lập) là hệ vật mà các vật trong hệ chỉ tương tác với nhau, không chịu tác dụng của lực từ các vật ngoài hệ.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">- A: Chỉ có lực của các vật trong hệ tác dụng lẫn nhau. Đây là cách phát biểu của định nghĩa hệ kín, nên đúng.</p><p class=\"text-base leading-relaxed my-2\">- B: Không có tác dụng của lực từ bên ngoài hệ. Đây là cách phát biểu tương đương của định nghĩa, nên đúng.</p><p class=\"text-base leading-relaxed my-2\">- C: Các nội lực từng đôi một trực đối nhau theo định luật III Niu-tơn. Vì hệ kín chỉ có nội lực, và nội lực giữa hai vật luôn là cặp lực-phản lực cùng độ lớn, ngược chiều, cùng giá (định luật III), nên đúng.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: cả A, B, C đều đúng, chọn D.</p>","options":["chỉ có những lực của các vật trong hệ tác dụng lẫn nhau.","không có tác dụng của những lực từ bên ngoài hệ.","các nội lực từng đôi trực đối nhau theo định luật III Niu tơn.","cả A, B, C đều đúng."],"answer":3}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chuyển động không theo nguyên tắc chuyển động bằng phản lực là chuyển động</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chuyển động bằng phản lực là chuyển động có được nhờ một phần của vật được phóng ra với vận tốc nhất định, vật nhận phản lực ngược chiều. Hệ kín được bảo toàn động lượng: $\\vec{p}_{\\text{trước}} = \\vec{p}_{\\text{sau}}$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Súng giật lùi khi bắn: viên đạn và khí thuốc súng được phóng ra phía trước, súng nhận phản lực ngược lại. Đây là chuyển động bằng phản lực.</p><p class=\"text-base leading-relaxed my-2\">B. Máy bay trực thăng: cánh quạt đẩy không khí xuống dưới, lực phản lực nâng máy bay lên. Đây không phải phóng một phần khối lượng của chính máy bay ra khỏi thân (không có dòng khí/nhiên liệu phụt ra từ động cơ theo nguyên tắc phản lực). Đây là chuyển động không theo nguyên tắc phản lực.</p><p class=\"text-base leading-relaxed my-2\">C. Tên lửa: khí cháy được phụt ra phía sau với vận tốc lớn, tên lửa nhận phản lực về phía trước. Đây là chuyển động bằng phản lực.</p><p class=\"text-base leading-relaxed my-2\">D. Con sứa biển: sứa co bóp, phụt nước ra phía sau để tiến về phía trước. Đây là chuyển động bằng phản lực.</p><p class=\"text-base leading-relaxed my-2\">Vậy đáp án là B.</p>","options":["giật lùi của súng khi bắn.","của máy bay trực thăng.","của tên lửa.","của con sứa biển."],"answer":1}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong chuyển động bằng phản lực nếu có một phần chuyển động theo một hướng thì phần còn lại phải</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định luật bảo toàn động lượng cho hệ kín (hệ vật ban đầu đứng yên): tổng động lượng trước và sau tương tác bằng nhau.</p><p class=\"text-base leading-relaxed my-2\">Ban đầu hệ đứng yên nên tổng động lượng bằng 0: $\\vec{p}_{\\text{tổng}} = 0$.</p><p class=\"text-base leading-relaxed my-2\">Sau khi phần một chuyển động theo một hướng với động lượng $\\vec{p}_1$, phần còn lại có động lượng $\\vec{p}_2$ sao cho $\\vec{p}_1 + \\vec{p}_2 = 0$, suy ra $\\vec{p}_2 = -\\vec{p}_1$.</p><p class=\"text-base leading-relaxed my-2\">Vậy $\\vec{p}_2$ ngược chiều với $\\vec{p}_1$, tức phần còn lại chuyển động theo hướng ngược lại.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng: C.</p>","options":["đứng yên.","chuyển động cùng hướng.","chuyển động theo hướng ngược lại.","chuyển động theo hướng vuông góc."],"answer":2}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Va chạm mềm, va chạm đàn hồi","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Va chạm nào sau đây là va chạm mềm?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Va chạm mềm là va chạm mà sau va chạm hai vật dính vào nhau và chuyển động cùng vận tốc (động năng không được bảo toàn, một phần chuyển thành nhiệt, biến dạng).</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Quả bóng đập vào tường rồi nảy ra: vật vẫn tách rời và chuyển động sau va chạm, đây là va chạm đàn hồi hoặc gần đàn hồi, không phải va chạm mềm.</p><p class=\"text-base leading-relaxed my-2\">B. Viên đạn xuyên vào và nằm gọn trong bao cát: đạn và bao cát dính vào nhau, cùng chuyển động sau va chạm. Đây là va chạm mềm.</p><p class=\"text-base leading-relaxed my-2\">C. Viên đạn xuyên qua tấm bia: đạn và bia tách rời sau va chạm, không dính nhau, không phải va chạm mềm.</p><p class=\"text-base leading-relaxed my-2\">D. Quả bóng tennis đập xuống sân: bóng nảy lên sau va chạm, tách khỏi sân, không phải va chạm mềm.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là B.</p>","options":["Quả bóng đang bay đập vào tường và nảy ra.","Viên đạn đang bay xuyên vào và nằm gọn trong bao cát.","Viên đạn xuyên qua một tấm bia trên đường bay của nó.","Quả bóng tennis đập xuống sân thi đấu."],"answer":1}$q$::jsonb, 145, $q$Va chạm mềm, va chạm đàn hồi$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trường hợp nào sau đây <strong>có thể</strong> xem là hệ kín?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ kín là hệ không chịu tác dụng của ngoại lực, hoặc tổng ngoại lực tác dụng lên hệ bằng không.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Hai viên bi chuyển động trên mặt phẳng nằm ngang nhưng có ma sát lăn, ma sát này là ngoại lực làm thay đổi động lượng của hệ. Loại.</p><p class=\"text-base leading-relaxed my-2\">B. Trên mặt phẳng nghiêng, trọng lực có thành phần song song với mặt phẳng nghiêng làm thay đổi động lượng của hệ. Loại.</p><p class=\"text-base leading-relaxed my-2\">C. Hai viên bi rơi trong không khí chịu trọng lực và lực cản của không khí, đều là ngoại lực. Loại.</p><p class=\"text-base leading-relaxed my-2\">D. Mặt phẳng nằm ngang không ma sát: trọng lực và phản lực pháp tuyến cân bằng theo phương thẳng đứng, không có ngoại lực theo phương ngang. Tổng ngoại lực bằng không, nên hệ có thể xem là hệ kín.</p><p class=\"text-base leading-relaxed my-2\">Chọn <b>D</b>.</p>","options":["Hai viên bi chuyển động trên mặt phẳng nằm ngang.","Hai viên bi chuyển động trên mặt phẳng nghiêng.","Hai viên bi rơi thẳng đứng trong không khí.","Hai viên bi chuyển động không ma sát trên mặt phẳng nằm ngang."],"answer":3}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Động lượng của vật bảo toàn trong trường hợp nào sau đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của một vật được bảo toàn khi hợp lực tác dụng lên vật bằng 0, tức là $\\vec{F}_{hl}=0$. Khi đó, theo định luật II Newton, $\\vec{F}_{hl}=\\dfrac{\\Delta \\vec{p}}{\\Delta t}=0$ nên $\\Delta \\vec{p}=0$, hay $\\vec{p}$ không đổi.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Vật chuyển động thẳng đều: vận tốc không đổi về độ lớn và hướng, nên $\\vec{p}=m\\vec{v}$ không đổi. Hợp lực bằng 0 nên động lượng được bảo toàn. <b>Đúng.</b></p><p class=\"text-base leading-relaxed my-2\">B. Chuyển động tròn đều: độ lớn vận tốc không đổi nhưng hướng thay đổi liên tục, nên $\\vec{p}$ thay đổi. Hợp lực là lực hướng tâm khác 0. <b>Loại.</b></p><p class=\"text-base leading-relaxed my-2\">C. Nhanh dần đều: vận tốc tăng, có gia tốc, hợp lực khác 0, nên $\\vec{p}$ thay đổi. <b>Loại.</b></p><p class=\"text-base leading-relaxed my-2\">D. Chậm dần đều: vận tốc giảm, có gia tốc, hợp lực khác 0, nên $\\vec{p}$ thay đổi. <b>Loại.</b></p><p class=\"text-base leading-relaxed my-2\">Kết luận: động lượng của vật được bảo toàn khi vật chuyển động thẳng đều trên mặt phẳng nằm ngang, đáp án <b>A</b>.</p>","options":["Vật đang chuyển động thẳng đều trên mặt phẳng nằm ngang.","Vật đang chuyển động tròn đều.","Vật đang chuyển động nhanh dần đều trên mặt phẳng nằm ngang không ma sát.","Vật đang chuyển động chậm dần đều trên mặt phẳng nằm ngang không ma sát."],"answer":0}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chuyển động bằng phản lực tuân theo định luật</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chuyển động bằng phản lực là chuyển động của vật được tạo ra nhờ phần khối lượng được phụt ra khỏi vật với một vận tốc nhất định, ví dụ tên lửa hay động cơ phản lực.</p><p class=\"text-base leading-relaxed my-2\">Hệ gồm vật và phần khối lượng phụt ra được xem là hệ kín (bỏ qua ngoại lực so với lực đẩy trong thời gian rất ngắn), nên động lượng của hệ được bảo toàn: $\\vec{p}_{\\text{trước}} = \\vec{p}_{\\text{sau}}$.</p><p class=\"text-base leading-relaxed my-2\">Vật thu được động lượng ngược chiều với phần khối lượng phụt ra, từ đó tạo ra chuyển động.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: chuyển động bằng phản lực tuân theo định luật bảo toàn động lượng.</p>","options":["bảo toàn công.","II Newton.","bảo toàn động lượng.","III Newton."],"answer":2}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng: trong hệ kín (không chịu ngoại lực, hoặc tổng ngoại lực bằng 0), tổng động lượng $\\vec{p} = \\sum m_i \\vec{v}_i$ của hệ được bảo toàn, tức là là một véctơ không đổi cả về hướng lẫn độ lớn.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Đúng về nội dung nhưng chưa nêu rõ tính chất véctơ của động lượng hệ. Đây là cách diễn đạt rút gọn của định luật.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng. Tổng động lượng của hệ kín là một véctơ không đổi, nghĩa là giữ nguyên cả hướng và độ lớn. Đây là phát biểu chính xác nhất của định luật.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng về mặt ứng dụng: tên lửa chuyển động nhờ phản lực, dựa trên bảo toàn động lượng của hệ tên lửa và khí phụt ra.</p><p class=\"text-base leading-relaxed my-2\">D. Về bản chất cũng đúng (động lượng hệ trước và sau tương tác bằng nhau), nhưng phát biểu chưa nêu điều kiện hệ kín và tính véctơ.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: phương án B là đáp án phát biểu đầy đủ và chính xác nhất.</p>","options":["Trong một hệ kín, động lượng của hệ được bảo toàn.","Trong một hệ kín, tổng động lượng của hệ là một véctơ không đổi cả về hướng và độ lớn.","Định luật bảo toàn động lượng là cơ sở của nguyên tắc chế tạo tên lửa vũ trụ.","Trong một hệ kín, động lượng của hệ trước và sau tương tác không đổi."],"answer":1}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu phát biểu <strong>sai</strong>. Một hệ vật được gọi là hệ kín (hệ cô lập) nếu</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ kín (hệ cô lập) là hệ mà các vật chỉ tương tác với nhau, không chịu tác dụng của vật ngoài hệ. Khi đó, mọi lực tương tác trong hệ đều là nội lực, và tổng các ngoại lực bằng không.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Đúng, vì đây chính là định nghĩa hệ kín.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng, vì hệ kín không có vật ngoài tác dụng, nên lực giữa các vật trong hệ là nội lực.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng, vì hệ không chịu ngoại lực nào (hoặc các ngoại lực triệt tiêu nhau), tức là $\\sum \\vec{F}_{ngoại} = \\vec{0}$.</p><p class=\"text-base leading-relaxed my-2\">D. Sai. Phát biểu này không đúng với điều kiện của hệ kín. Điều đặc trưng của hệ kín là tổng <i>ngoại lực</i> bằng $\\vec{0}$, còn “tổng hợp lực tác dụng lên hệ” không xác định rõ là ngoại lực hay nội lực, nên không thể dùng để nhận biết hệ kín.</p><p class=\"text-base leading-relaxed my-2\">Vậy phương án sai là <b>D</b>.</p>","options":["các vật trong hệ chỉ tương tác với nhau mà không tương tác với các vật khác ngoài hệ.","lực tác dụng lên các vật trong hệ là nội lực.","tổng các ngoại lực tác dụng lên vật trong hệ bù trừ nhau.","tổng hợp lực tác dụng lên hệ không đổi."],"answer":3}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>sai</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Định nghĩa hệ kín:</strong> Hệ kín (hệ cô lập) là hệ không có ngoại lực tác dụng lên hệ, hoặc tổng ngoại lực bằng 0. Khi đó động lượng của hệ được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\"><strong>Xét phương án A:</strong> Hệ vật – Trái Đất không phải lúc nào cũng là hệ kín, vì vật có thể chịu tác dụng của các lực từ bên ngoài như lực đẩy, lực ma sát với môi trường, lực do vật khác tác dụng. Do đó phát biểu \"luôn được coi là hệ kín\" là <strong>sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>Xét phương án B:</strong> Hệ vật – Trái Đất chỉ gần đúng là hệ kín khi ngoại lực không đáng kể so với nội lực. Phát biểu này <strong>đúng</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>Xét phương án C:</strong> Trong vụ nổ, nội lực (lực tương tác giữa các mảnh) rất lớn và rất ngắn, ngoại lực không đáng kể trong thời gian xảy ra nổ nên hệ được coi gần đúng là kín. Phát biểu này <strong>đúng</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>Xét phương án D:</strong> Trong va chạm, lực tương tác giữa các vật rất lớn, ngoại lực không đáng kể trong thời gian va chạm rất ngắn nên hệ được coi gần đúng là kín. Phát biểu này <strong>đúng</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Phát biểu sai là phương án A.</p>","options":["Hệ vật – Trái Đất luôn được coi là hệ kín.","Hệ vật – Trái Đất chỉ gần đúng là hệ kín.","Trong các vụ nổ, hệ vật có thể coi như gần đúng là hệ kín trong thời gian ngắn xảy ra hiện tượng.","Trong va chạm, hệ vật có thể coi gần đúng là hệ kín trong thời gian ngắn xảy ra hiện tượng."],"answer":0}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hệ vật - Trái Đất chỉ gần <strong>đúng</strong> là hệ kín vì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ kín là hệ không chịu tác dụng của ngoại lực (hoặc ngoại lực triệt tiêu nhau).</p><p class=\"text-base leading-relaxed my-2\">Hệ vật - Trái Đất chịu tác dụng của lực hấp dẫn từ các thiên thể khác trong vũ trụ (Mặt Trời, Mặt Trăng, ...). Các lực này luôn tồn tại nhưng rất nhỏ so với nội lực giữa vật và Trái Đất, nên có thể bỏ qua.</p><p class=\"text-base leading-relaxed my-2\">Vì vẫn tồn tại ngoại lực, hệ chỉ <em>gần đúng</em> là hệ kín.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng: D.</p>","options":["Trái Đất luôn chuyển động.","Trái Đất luôn luôn hút vật.","vật luôn chịu tác dụng của trọng lực.","luôn tồn tại các lực hấp dẫn từ các thiên thể trong vũ trụ tác dụng lên vật."],"answer":3}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>sai</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Kiến thức:</strong> Hệ kín (hệ cô lập) là hệ không chịu ngoại lực, hoặc tổng ngoại lực tác dụng lên hệ bằng không. Khi đó động lượng của hệ được bảo toàn: $\\vec{p}=\\text{const}$.</p><p class=\"text-base leading-relaxed my-2\"><strong>Xét từng phương án:</strong></p><p class=\"text-base leading-relaxed my-2\">A. Đúng. Vật rơi tự do chịu tác dụng của trọng lực, là ngoại lực đối với vật, nên vật không phải hệ kín.</p><p class=\"text-base leading-relaxed my-2\">B. Sai. Hệ kín được định nghĩa bởi việc ngoại lực bằng không (hoặc triệt tiêu), không phải bởi việc ngoại lực \"không đổi\". Một ngoại lực không đổi khác không vẫn có thể làm thay đổi động lượng.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng. Hệ gồm vật và Trái Đất, khi bỏ qua tương tác với các vật khác, thì lực tác dụng lên hệ chỉ là nội lực, nên hệ được coi là kín.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng. Khi không có ngoại lực, tổng ngoại lực bằng không nên động lượng của hệ được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Phát biểu sai là phương án B.</p>","options":["Vật rơi tự do không phải là hệ kín vì trọng lực tác dụng lên vật là ngoại lực.","Một hệ gọi là hệ kín khi ngoại lực tác dụng lên hệ không đổi.","Hệ gồm vật rơi tự do và Trái Đất, được xem là hệ kín khi bỏ qua lực tương tác giữa hệ vật với các vật khác.","Khi không có ngoại lực tác dụng lên hệ thì động lượng của hệ được bảo toàn."],"answer":1}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>sai</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Kiến thức:</strong> Hệ kín (hệ cô lập) là hệ không có ngoại lực tác dụng, hoặc các ngoại lực tác dụng lên hệ triệt tiêu nhau (tổng hợp lực bằng 0). Khi đó động lượng của hệ được bảo toàn: $\\vec{p}_{\\text{hệ}} = \\text{const}$.</p><p class=\"text-base leading-relaxed my-2\"><strong>Xét từng phương án:</strong></p><p class=\"text-base leading-relaxed my-2\">A. Đúng. Đây là nội dung định luật bảo toàn động lượng: hệ không chịu ngoại lực thì động lượng của hệ bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng. Vật rơi tự do chịu tác dụng của trọng lực $\\vec{P}$ là ngoại lực nên vật không phải hệ kín.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng. Hệ gồm vật và Trái Đất, nếu bỏ qua tương tác với các vật khác (Mặt Trời, các hành tinh…) thì hệ coi như kín.</p><p class=\"text-base leading-relaxed my-2\">D. Sai. Hệ kín không phụ thuộc vào việc ngoại lực có đổi hay không; điều kiện là ngoại lực bằng không (hoặc triệt tiêu). Một ngoại lực không đổi khác 0 vẫn làm hệ không kín.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Phát biểu sai là D.</p>","options":["Khi không có ngoại lực tác dụng lên hệ thì động lượng của hệ được bảo toàn.","Vật rơi tự do không phải là hệ kín vì trọng lực tác dụng lên vật là ngoại lực.","Hệ gồm \"Vật rơi tự do và Trái Đất\" được xem là hệ kín khi bỏ qua lực tương tác giữa hệ vật với các vật khác (Mặt Trời, các hành tinh.).","Một hệ gọi là hệ kín khi ngoại lực tác dụng lên hệ không đổi."],"answer":3}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trường hợp nào, hệ vật <strong>không</strong> được coi là hệ kín?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ kín (hệ cô lập) là hệ không chịu tác dụng của ngoại lực, hoặc tổng các ngoại lực tác dụng lên hệ bằng không. Khi đó động lượng của hệ được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Hệ không chịu tác dụng của lực nào: không có ngoại lực, nên là hệ kín.</p><p class=\"text-base leading-relaxed my-2\">B. Hệ chỉ chịu tác dụng của lực cản, ma sát: lực cản và ma sát từ môi trường bên ngoài là ngoại lực khác không, nên hệ không kín.</p><p class=\"text-base leading-relaxed my-2\">C. Hệ không có ngoại lực tác dụng: đúng định nghĩa hệ kín.</p><p class=\"text-base leading-relaxed my-2\">D. Hệ chỉ có nội lực giữa các vật trong hệ: nội lực không làm thay đổi tổng động lượng của hệ, nên hệ là hệ kín.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án B.</p>","options":["Hệ không chịu tác dụng của lực nào.","Hệ chỉ chịu tác dụng của lực cản, ma sát.","Hệ không có ngoại lực tác dụng.","Hệ chỉ có nội lực giữa các vật trong hệ."],"answer":1}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Động lượng của hệ vật bảo toàn trong trường hợp nào?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng: động lượng toàn phần của một hệ kín (hệ cô lập) được bảo toàn, tức là $\\vec{p} = \\sum m_i\\vec{v_i}$ không đổi theo thời gian.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện áp dụng: tổng ngoại lực tác dụng lên hệ bằng không, $\\sum \\vec{F}_{ngoại} = \\vec{0}$. Khi đó $\\dfrac{d\\vec{p}}{dt} = \\sum \\vec{F}_{ngoại} = \\vec{0}$, suy ra $\\vec{p}$ không đổi.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Sai: hệ chịu ngoại lực nhưng tổng hợp khác không thì động lượng thay đổi.</p><p class=\"text-base leading-relaxed my-2\">B. Sai: không có lực cản chưa đủ, còn cần các ngoại lực khác cân bằng nhau.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng: các ngoại lực cân bằng có hợp lực bằng không nên động lượng bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">D. Sai: nội lực luôn tồn tại khi các vật tương tác, nhưng theo định luật III Newton chúng triệt tiêu nhau trong hệ nên không làm thay đổi tổng động lượng; việc không có nội lực không phải điều kiện bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: động lượng của hệ được bảo toàn khi hệ chịu tác dụng các ngoại lực cân bằng. Đáp án <b>C</b>.</p>","options":["Hệ chịu tác dụng của các ngoại lực.","Hệ không chịu tác dụng của lực cản.","Hệ chịu tác dụng các ngoại lực cân bằng.","Hệ không có nội lực tương tác giữa các vật."],"answer":2}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hệ hai viên bi được coi là hệ kín (cô lập) trong trường hợp chúng chuyển động</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ kín (cô lập) là hệ không chịu tác dụng của ngoại lực, hoặc tổng các ngoại lực bằng không.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">- A. Rơi tự do: các viên bi chịu trọng lực $P$ hướng xuống, ngoại lực khác không, nên không phải hệ kín.</p><p class=\"text-base leading-relaxed my-2\">- B. Trên mặt nghiêng: thành phần trọng lực dọc mặt nghiêng khác không, nên tổng ngoại lực khác không, không phải hệ kín.</p><p class=\"text-base leading-relaxed my-2\">- C. Trên mặt sàn ngang: có lực ma sát của sàn tác dụng lên bi, là ngoại lực, nên không phải hệ kín.</p><p class=\"text-base leading-relaxed my-2\">- D. Không ma sát trên mặt ngang: trọng lực và phản lực của mặt ngang cân bằng nhau theo phương thẳng đứng, không có lực ngang tác dụng, tổng ngoại lực bằng không. Hệ là hệ kín.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng: D.</p>","options":["rơi tự do.","trên mặt nghiêng.","trên mặt sàn ngang.","không ma sát trên mặt ngang."],"answer":3}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Xét một hệ cô lập gồm hai vật có khối lượng $m_{1}$, $m_{2}$. Hai vật va chạm nhau, vận tốc trước và sau va chạm của mỗi vật theo thứ tự ${\\overset{\\rightarrow}{v}}_{1},$ ${\\overset{\\rightarrow}{v}}_{1}'$ và ${\\overset{\\rightarrow}{v}}_{2},$ ${\\overset{\\rightarrow}{v}}_{2}'.$ Hệ thức định luật bảo toàn động lượng của hệ là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ hai vật là hệ cô lập nên tổng động lượng của hệ được bảo toàn trong quá trình va chạm.</p><p class=\"text-base leading-relaxed my-2\">Động lượng của mỗi vật: $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{p}=m\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}$. Động lượng của hệ trước va chạm là $m_{1}\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{1}+m_{2}\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{2}$, sau va chạm là $m_{1}\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{1}'+m_{2}\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{2}'$.</p><p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng: tổng động lượng trước va chạm bằng tổng động lượng sau va chạm.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m_{1}\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{1}+m_{2}\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{2}=m_{1}\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{1}'+m_{2}\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}_{2}'$</p><p class=\"text-base leading-relaxed my-2\">Đáp án D. Các phương án A, B, C sai vì hoặc sai dấu/tổng bằng không, hoặc dùng độ lớn vận tốc thay vì vectơ vận tốc.</p>","options":["$m_{1}v_{1}+m_{2}v_{2}+m_{1}v_{1}'+m_{2}v_{2}'=0.$","$m_{1}{\\overset{\\rightarrow}{v}}_{1}+m_{2}{\\overset{\\rightarrow}{v}}_{2}+m_{1}{\\overset{\\rightarrow}{v}}_{1}'+m_{2}{\\overset{\\rightarrow}{v}}_{2}'=\\overset{\\rightarrow}{0}.$","$m_{1}v_{1}+m_{2}v_{2}=m_{1}v_{1}'+m_{2}v_{2}'.$","$m_{1}{\\overset{\\rightarrow}{v}}_{1}+m_{2}{\\overset{\\rightarrow}{v}}_{2}=m_{1}{\\overset{\\rightarrow}{v}}_{1}'+m_{2}{\\overset{\\rightarrow}{v}}_{2}'.$"],"answer":3}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Xét một hệ vật chịu tác dụng của các ngoại lực cân bằng. Cho các vật bên trong hệ tương tác lẫn nhau thì động lượng của hệ sau tương tác</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng: một hệ vật cô lập (hoặc có tổng ngoại lực bằng không, tức các ngoại lực cân bằng) thì tổng động lượng của hệ được bảo toàn.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện áp dụng: tổng ngoại lực tác dụng lên hệ bằng 0, nên chỉ có nội lực (lực tương tác giữa các vật trong hệ) hoạt động.</p><p class=\"text-base leading-relaxed my-2\">Theo định luật III Newton, nội lực giữa hai vật luôn trực đối: $\\vec{F}_{12}=-\\vec{F}_{21}$. Khi đó tổng động lượng thay đổi: $\\Delta\\vec{p}_1+\\Delta\\vec{p}_2=(\\vec{F}_{12}+\\vec{F}_{21})\\Delta t=\\vec{0}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\vec{p}_{\\text{sau}}=\\vec{p}_{\\text{trước}}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: động lượng của hệ sau tương tác bằng động lượng của hệ trước tương tác. Đáp án C.</p>","options":["lớn hơn so với động lượng của hệ trước tương tác.","nhỏ hơn so với động lượng của hệ trước tương tác.","bằng với động lượng của hệ trước tương tác.","không bằng động lượng của hệ trước tương tác."],"answer":2}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho các vật bên trong một hệ kín tương tác lẫn nhau thì độ biến thiên động lượng của hệ có giá trị</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ kín là hệ không chịu tác dụng của ngoại lực, hoặc tổng ngoại lực bằng không.</p><p class=\"text-base leading-relaxed my-2\">Theo định luật bảo toàn động lượng, với hệ kín: $\\vec{p}_{\\text{hệ}} = \\vec{p}_1 + \\vec{p}_2 + \\dots = \\text{const}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\Delta \\vec{p}_{\\text{hệ}} = \\vec{p}_{\\text{hệ, sau}} - \\vec{p}_{\\text{hệ, trước}} = 0$.</p><p class=\"text-base leading-relaxed my-2\">Vậy độ biến thiên động lượng của hệ kín bằng không. Đáp án đúng là A.</p>","options":["bằng không.","khác không.","âm.","dương."],"answer":0}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn động lượng cho hệ kín","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật đang đứng yên thì bị tách thành hai phần, phần thứ nhất $(1)$ có khối lượng $m_{1}$ với vận tốc $v_{1},$,= phần thứ hai $(2)$ có khối lượng $ m_{2} = 2m_{1}$với vận tốc $ v_{2}.$ Kết luận nào sau đây <strong>đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Áp dụng định luật bảo toàn động lượng:</strong> Hệ kín (vật ban đầu đứng yên) nên tổng động lượng trước và sau khi tách bằng nhau. Trước khi tách, $\\vec{p}=\\vec{0}$.</p><p class=\"text-base leading-relaxed my-2\">Sau khi tách: $\\vec{p}_1+\\vec{p}_2=\\vec{0}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\vec{p}_1=-\\vec{p}_2$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $|\\vec{p}_1|=|\\vec{p}_2|$, tức là hai phần có độ lớn động lượng bằng nhau. Hai vectors ngược chiều nhau nên không phải là bằng nhau về vectơ.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra: $m_1v_1=m_2v_2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$v_2=\\dfrac{m_1}{m_2}v_1=\\dfrac{v_1}{2}$ (độ lớn), nên động lượng hai phần bằng nhau dù khối lượng và vận tốc khác nhau.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Phương án A đúng. Phương án B, C sai. Phương án D sai vì hai động lượng ngược hướng nên không bằng nhau về vectơ.</p>","options":["Phần $1$ và phần $2$ có độ lớn động lượng bằng nhau.","Phần $1$ có độ lớn động lượng lớn hơn phần $2.$","Phần $1$ có độ lớn động lượng nhỏ hơn phần $2.$","Phần $1$ và phần $2$ có động lượng luôn bằng nhau."],"answer":0}$q$::jsonb, 144, $q$Định luật bảo toàn động lượng cho hệ kín$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Va chạm mềm, va chạm đàn hồi","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai viên bi A và B có cùng khối lượng. Bi B đứng yên, bi A chuyển động với vận tốc là $\\overset{\\rightarrow}{v}$ trên mặt phẳng ngang va chạm vào bi B. Sau va chạm hai viên bi dính vào nhau và chuyển động cùng vận tốc $\\overset{\\rightarrow}{v}'$. Điều nào sau đây <strong>sai</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ hai viên bi là hệ kín trong thời gian va chạm (ngoại lực như trọng lực và phản lực của mặt phẳng ngang cân bằng nhau), nên áp dụng định luật bảo toàn động lượng.</p><p class=\"text-base leading-relaxed my-2\">Chọn chiều dương là chiều của $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}$. Động lượng trước va chạm: $p_{\\text{trước}} = m_A v + m_B \\cdot 0 = mv$.</p><p class=\"text-base leading-relaxed my-2\">Sau va chạm hai bi dính vào nhau, chuyển động với vận tốc $v'$, tổng khối lượng $2m$: $p_{\\text{sau}} = (m_A + m_B)v' = 2mv'$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Bảo toàn động lượng: $mv = 2mv'$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$v' = \\dfrac{v}{2} = 0{,}5v$, với $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}'$ cùng phương, cùng chiều $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. $v' = 2v$ là sai, vì kết quả đúng là $v' = 0{,}5v$.</p><p class=\"text-base leading-relaxed my-2\">B. $v' = 0{,}5v$ là đúng.</p><p class=\"text-base leading-relaxed my-2\">C. Hai vật dính vào nhau sau va chạm là va chạm mềm, đúng.</p><p class=\"text-base leading-relaxed my-2\">D. Vận tốc $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}'$ cùng phương, cùng chiều $\\overset{$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow}{v}$, đúng.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: phương án sai là A.</p>","options":["$v'=2v.$","$v'=0,5v.$","Va chạm trên gọi là va chạm mềm.","$\\overset{\\rightarrow}{v}'$ cùng phương và cùng chiều $\\overset{\\rightarrow}{v}.$ \n<strong>[TRẮC NGHIỆM ĐỊNH LƯỢNG</strong>"],"answer":0}$q$::jsonb, 145, $q$Va chạm mềm, va chạm đàn hồi$q$)) as v(q, tid, tname)
